"use client";

import { useId, useState } from "react";

export function OtpInputTailwind({ length = 6 }) {
  const id = useId();
  const [value, setValue] = useState("");
  const [focused, setFocused] = useState(false);
  return (
    <div className="inline-flex flex-col gap-2.5">
      <label htmlFor={id} className="text-sm font-medium text-zinc-400">Verification code</label>
      <div className="relative flex gap-2">
        <input id={id} value={value} maxLength={length} inputMode="numeric" autoComplete="one-time-code" onFocus={() => setFocused(true)} onBlur={() => setFocused(false)} onChange={(e) => setValue(e.target.value.replace(/\D/g, "").slice(0, length))} className="absolute inset-0 z-10 bg-transparent text-transparent caret-transparent outline-none" />
        {Array.from({ length }, (_, i) => {
          const active = focused && i === Math.min(value.length, length - 1);
          return (
            <div key={i} aria-hidden="true" className={`grid h-14 w-12 place-items-center rounded-xl border bg-zinc-900 text-2xl font-semibold text-zinc-100 transition ${active ? "border-indigo-500 ring-4 ring-indigo-500/25" : "border-zinc-800"}`}>
              {value[i] ?? (active ? <span className="h-6 w-0.5 animate-pulse bg-indigo-400" /> : null)}
            </div>
          );
        })}
      </div>
    </div>
  );
}
